SPARQL:
SELECT ?magazine ?magazineLabel ?inception WHERE {
  VALUES ?name { "Arthur's Magazine"@en "First for Women"@en }
  ?magazine rdfs:label ?name.
  ?magazine wdt:P31 wd:Q41298.
  ?magazine wdt:P571 ?inception.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ASC(?inception)
LIMIT 1

SELECT DISTINCT ?company ?companyLabel ?hq ?hqLabel WHERE {
  ?family rdfs:label "Oberoi family"@en.
  {
    ?company wdt:P127 ?family.
  }
  UNION
  {
    ?company wdt:P112 ?founder.
    ?founder wdt:P53 ?family.
  }
  ?company wdt:P159 ?hq.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?namedAfter ?namedAfterLabel WHERE {
  ?milhouse rdfs:label "Milhouse Van Houten"@en.
  ?milhouse wdt:P138 ?namedAfter.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?wife ?wifeLabel ?nationality ?nationalityLabel WHERE {
  ?person wdt:P31 wd:Q5;
          wdt:P1477 ?birthName.
  FILTER(LCASE(STR(?birthName)) = "james henry miller").
  ?person wdt:P26 ?wife.
  ?wife wdt:P21 wd:Q6581072;
        wdt:P27 ?nationality.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?itemAltLabel WHERE {
  ?item wdt:P31 wd:Q11173.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
  FILTER(LCASE(STR(?itemLabel)) = "cadmium chloride")
}

SELECT ?player ?playerLabel (COUNT(DISTINCT ?event) AS ?titles) WHERE {
  VALUES ?name { "Henri Leconte"@en "Jonathan Stark"@en }
  ?player rdfs:label ?name.
  ?player wdt:P31 wd:Q5; wdt:P641 wd:Q847.
  ?event wdt:P1346 ?player.
  ?event (wdt:P361+|wdt:P629/wdt:P361*) ?tournament.
  VALUES ?tournament { wd:Q132616 wd:Q134233 wd:Q132771 wd:Q132607 }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?player ?playerLabel
ORDER BY DESC(?titles)
LIMIT 1

SELECT ?genus ?genusLabel WHERE {
  VALUES ?country { wd:Q668 }  # India
  ?species wdt:P105 wd:Q7432 ;
           wdt:P171 ?genus ;
           wdt:P183 ?country .
  ?genus wdt:P105 wd:Q34740 .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?genus ?genusLabel
HAVING (COUNT(DISTINCT ?species) = 1)

SELECT ?item ?itemLabel WHERE {
  ?item wdt:P31 wd:Q5;
        wdt:P641 wd:Q180634;
        wdt:P27 wd:Q55, wd:Q1028;
        wdt:P1399 ?conviction.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT (MIN(YEAR(?firstAir)) AS ?year) WHERE {
  SERVICE wikibase:mwapi {
    bd:serviceParam wikibase:api "EntitySearch";
                    wikibase:endpoint "www.wikidata.org";
                    mwapi:search "House of Anubis";
                    mwapi:language "en".
    ?item wikibase:apiOutputItem mwapi:item.
  }
  ?item wdt:P31 wd:Q5398426;
        wdt:P495 wd:Q55, wd:Q31;
        wdt:P577 ?firstAir.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?track ?trackLabel ?length ?unitLabel WHERE {
  ?event rdfs:label "2013 Liqui Moly Bathurst 12 Hour"@en.
  ?event wdt:P276 ?track.
  ?track p:P2043 ?lenStmt.
  ?lenStmt ps:P2043 ?length;
           wikibase:quantityUnit ?unit.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?person ?personLabel WHERE {
  ?release rdfs:label "Fast Cars, Danger, Fire and Knives"@en.

  {
    ?release p:P175 ?stmt.
    ?stmt ps:P175 ?person.
    ?stmt pq:P3831 ?role.
    ?role rdfs:label ?roleLabel.
    FILTER(CONTAINS(LCASE(STR(?roleLabel)), "featur") || CONTAINS(LCASE(STR(?roleLabel)), "guest"))
  }
  UNION
  {
    ?release wdt:P527 ?track.
    ?track p:P175 ?tstmt.
    ?tstmt ps:P175 ?person.
    ?tstmt pq:P3831 ?trole.
    ?trole rdfs:label ?troleLabel.
    FILTER(CONTAINS(LCASE(STR(?troleLabel)), "featur") || CONTAINS(LCASE(STR(?troleLabel)), "guest"))
  }

  ?person wdt:P106 ?occ.
  ?occ rdfs:label ?occLabel.
  FILTER(REGEX(LCASE(STR(?occLabel)), "record label executive|record executive"))

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?narrator ?narratorLabel WHERE {
  ?frontier rdfs:label "Frontier"@en;
            wdt:P2438 ?narrator.
  ?film wdt:P31 wd:Q11424;
        rdfs:label "Gunmen from Laredo"@en;
        wdt:P161 ?narrator.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?origin ?originLabel WHERE {
  ?band rdfs:label "Die Rhöner Säuwäntzt"@de.
  ?band wdt:P136/wdt:P495 ?origin.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?game ?gameLabel WHERE {
  # Identify Malcolm Smith (born 1989)
  ?person wdt:P31 wd:Q5;
          rdfs:label "Malcolm Smith"@en;
          wdt:P569 ?dob.
  FILTER (YEAR(?dob) = 1989)

  {
    # Participant in event with role "Most Valuable Player"
    ?person p:P1344 ?partStmt.
    ?partStmt ps:P1344 ?game;
              pq:P2868 ?role.
    ?role rdfs:label ?roleLabel.
    FILTER(CONTAINS(LCASE(?roleLabel), "most valuable player"))
    ?game wdt:P179 wd:Q41487.  # Super Bowl series
  }
  UNION
  {
    # Award received with qualifier linking to the game
    ?person p:P166 ?awardStmt.
    ?awardStmt ps:P166 ?award.
    ?award rdfs:label ?awardLabel.
    FILTER(CONTAINS(LCASE(?awardLabel), "most valuable player"))
    ?awardStmt pq:P642 ?game.
    ?game wdt:P179 wd:Q41487.  # Super Bowl series
  }

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?highway ?highwayLabel WHERE {
  ?highway (rdfs:label|skos:altLabel) "Midland Trail"@en.
  {
    ?highway wdt:P2789 ?zilpo.
  } UNION {
    ?zilpo wdt:P2789 ?highway.
  }
  ?zilpo (rdfs:label|skos:altLabel) "Zilpo Road"@en.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
  FILTER(REGEX(STR(?highwayLabel), "^U\\.?S\\.?\\s+(Route|Highway)\\b", "i"))
}

SELECT DISTINCT ?year WHERE {
  ?film wdt:P31 wd:Q11424;
        rdfs:label "The Great Outdoors"@en;
        wdt:P577 ?pubdate.
  FILTER(YEAR(?pubdate) = 1988)

  ?film wdt:P161 ?person.

  {
    SELECT ?person WHERE {
      ?person wdt:P1411 ?nom .
      ?nom wdt:P361 wd:Q19020 .
    }
    GROUP BY ?person
    HAVING (COUNT(DISTINCT ?nom) >= 4)
  }

  ?person p:P166 ?st .
  ?st ps:P166 ?award .
  ?award rdfs:label ?al .
  FILTER(LANG(?al) = "en" && CONTAINS(LCASE(?al), "hollywood walk of fame"))
  OPTIONAL { ?st pq:P585 ?d1 }
  OPTIONAL { ?st pq:P580 ?d2 }
  BIND(YEAR(COALESCE(?d1, ?d2)) AS ?year)

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
LIMIT 1

SELECT DISTINCT ?member ?memberLabel WHERE {
  ?work rdfs:label "Hurt Locker: The Musical"@en.
  ?work wdt:P86 ?band.
  ?band wdt:P136 ?genre.
  ?genre wdt:P279* wd:Q38848.
  FILTER(
    EXISTS { ?band wdt:P17 wd:Q30 } ||
    EXISTS { ?band wdt:P495 wd:Q30 } ||
    EXISTS { ?band wdt:P740/wdt:P17 wd:Q30 }
  ).
  ?member wdt:P31 wd:Q5.
  ?member p:P463 ?membership.
  ?membership ps:P463 ?band.
  FILTER NOT EXISTS { ?membership pq:P582 ?end }.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?network ?networkLabel WHERE {
  ?episode wdt:P31 wd:Q21191270;
           rdfs:label "Human Error"@en.
  { ?episode wdt:P361 ?season. } UNION { ?episode wdt:P179 ?season. }
  ?season wdt:P31 wd:Q3464665.
  ?season p:P179 ?seriesStmt.
  ?seriesStmt ps:P179 ?series;
              pq:P1545 "3".
  FILTER NOT EXISTS {
    ?otherEpisode wdt:P31 wd:Q21191270.
    { ?otherEpisode wdt:P361 ?season. } UNION { ?otherEpisode wdt:P179 ?season. }
    ?otherEpisode wdt:P155 ?episode.
  }
  ?episode wdt:P449 ?network.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT (YEAR(?date) AS ?year) WHERE {
  ?album rdfs:label "Dua Lipa"@en;
         wdt:P175 ?artist;
         wdt:P577 ?date.
  ?artist rdfs:label "Dua Lipa"@en.
  ?song rdfs:label "New Rules"@en.
  { ?song wdt:P361 ?album. }
  UNION
  { ?album wdt:P658 ?song. }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
LIMIT 1

SELECT DISTINCT ?state ?stateLabel WHERE {
  wd:Q1071929 p:P39 ?stmt.
  ?stmt pq:P1545 "32".
  ?stmt ps:P39 ?position.
  {
    ?position wdt:P1001|wdt:P131 ?state.
  }
  UNION
  {
    ?stmt pq:P642 ?state.
  }
  ?state wdt:P31 wd:Q35657.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?state ?stateLabel WHERE {
  ?store wdt:P169 ?ceo.
  ?ceo rdfs:label "Warren Bryant"@en.
  ?store wdt:P159 ?hq.
  ?hq wdt:P131* ?state.
  ?state wdt:P31 wd:Q35657.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?replaced ?replacedLabel WHERE {
  ?donahue wdt:P31 wd:Q5; rdfs:label ?donahueName.
  FILTER(LANG(?donahueName) = "en").
  FILTER(CONTAINS(LCASE(?donahueName), "donahue")).
  {
    ?donahue wdt:P1365 ?replaced.
  }
  UNION
  {
    ?donahue p:P39 ?st.
    ?st pq:P1365 ?replaced.
  }
  ?replaced wdt:P31 wd:Q5;
            wdt:P106 wd:Q82955;
            wdt:P27 wd:Q30.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wikibase: <http://wikiba.se/ontology#>
PREFIX bd: <http://www.bigdata.com/rdf#>

SELECT ?band ?bandLabel ?inception WHERE {
  VALUES ?name { "Hole"@en "The Wolfhounds"@en }
  ?band wdt:P31/wdt:P279* wd:Q215380;
        rdfs:label ?name;
        wdt:P571 ?inception.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ASC(?inception)
LIMIT 1

SELECT ?endYear WHERE {
  wd:Q8683 wdt:P582 ?end.
  BIND(YEAR(?end) AS ?endYear)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?film ?filmLabel ?director ?directorLabel WHERE {
  VALUES ?label { "Quality Cafe"@en "Quality Café"@en }
  ?place rdfs:label ?label.
  ?place wdt:P131* wd:Q65.
  ?film wdt:P31 wd:Q11424;
        wdt:P915 ?place;
        wdt:P577 ?date;
        wdt:P57 ?director.
  FILTER(YEAR(?date) = 2003)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?property ?propertyLabel ?sharedValue ?sharedValueLabel WHERE {
  {
    wd:Q216554 wdt:P101 ?sharedValue.
    wd:Q191871 wdt:P101 ?sharedValue.
    BIND(wd:P101 AS ?property)
  }
  UNION
  {
    wd:Q216554 wdt:P106 ?sharedValue.
    wd:Q191871 wdt:P106 ?sharedValue.
    BIND(wd:P106 AS ?property)
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wikibase: <http://wikiba.se/ontology#>
PREFIX bd: <http://www.bigdata.com/rdf#>

ASK {
  {
    ?np rdfs:label "The New Pornographers"@en;
        wdt:P136/wdt:P279* wd:Q11399;
        wdt:P495 wd:Q30.
  }
  {
    ?kol rdfs:label "Kings of Leon"@en;
         wdt:P136/wdt:P279* wd:Q11399;
         wdt:P495 wd:Q30.
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?item ?itemLabel ?city ?cityLabel WHERE {
  VALUES ?name {
    "750 7th Avenue"@en
    "750 Seventh Avenue"@en
    "101 Park Avenue"@en
  }
  ?item (rdfs:label|skos:altLabel) ?name.
  ?item wdt:P131* ?city.
  ?city wdt:P31/wdt:P279* wd:Q515.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?actress ?actressLabel WHERE {
  ?character rdfs:label "Kimberly Ann Hart"@en.
  ?work p:P161 ?castStatement.
  ?castStatement ps:P161 ?actress;
                 pq:P453 ?character.
  ?actress wdt:P21 wd:Q6581072.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?person ?personLabel ?birthDate WHERE {
  VALUES ?name {"Pablo Trapero"@en "Aleksander Ford"@en}
  ?person rdfs:label ?name.
  ?person wdt:P31 wd:Q5;
          wdt:P569 ?birthDate.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?birthDate
LIMIT 1

SELECT ?item ?itemLabel ?isWomensMagazine WHERE {
  VALUES ?name { "Jane"@en "First for Women"@en }
  ?item rdfs:label ?name.
  ?item wdt:P31/wdt:P279* wd:Q41298.
  BIND(EXISTS {
    ?item wdt:P31/wdt:P279* ?cls.
    ?cls rdfs:label "women's magazine"@en.
  } AS ?isWomensMagazine)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?profession ?professionLabel WHERE {
  VALUES ?name { "Nicholas Ray"@en "Elia Kazan"@en }
  ?person rdfs:label ?name;
          wdt:P31 wd:Q5;
          wdt:P106 ?profession.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?profession ?professionLabel
HAVING (COUNT(DISTINCT ?name) = 2)

SELECT DISTINCT ?hq ?hqLabel WHERE {
  ?company rdfs:label|skos:altLabel "Aixam"@en;
           wdt:P31/wdt:P279* wd:Q163740.
  {
    ?company wdt:P127 ?buyer.
  } UNION {
    ?company wdt:P749 ?buyer.
  } UNION {
    ?buyer wdt:P355 ?company.
  }
  ?buyer wdt:P159 ?hq.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?film ?filmLabel WHERE {
  VALUES ?name { "Adam Clayton Powell"@en "The Saimaa Gesture"@en }
  ?film (rdfs:label|skos:altLabel) ?name.
  ?film wdt:P31/wdt:P279* wd:Q93204.
  ?film wdt:P921 ?band.
  {
    ?band wdt:P31/wdt:P279* wd:Q5741069.
    ?band (wdt:P495|wdt:P17) wd:Q33.
  }
  UNION
  {
    ?band wdt:P31/wdt:P279* wd:Q215380.
    ?band (wdt:P495|wdt:P17) wd:Q33.
    ?band wdt:P136/wdt:P279* wd:Q11399.
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?person ?personLabel WHERE {
  VALUES ?name { "David Lee Roth"@en "Cia Berg"@en }
  ?person rdfs:label ?name.
  ?person wdt:P31 wd:Q5.
  {
    ?person wdt:P166 ?award.
    ?award rdfs:label "Rock and Roll Hall of Fame"@en.
  }
  UNION
  {
    ?person wdt:P463 ?org.
    ?org rdfs:label "Rock and Roll Hall of Fame"@en.
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?county ?countyLabel WHERE {
  VALUES ?guweLabel { "Guwe Secondary School"@en }
  ?guwe rdfs:label ?guweLabel;
        wdt:P17 wd:Q954.

  ?prop a wikibase:Property;
        rdfs:label ?propLabel;
        wikibase:directClaim ?wdtProp.
  FILTER(LANG(?propLabel) = "en").
  FILTER(REGEX(STR(?propLabel), "sister school|twin school|partner school", "i")).

  { ?guwe ?wdtProp ?sister } UNION { ?sister ?wdtProp ?guwe }.
  ?sister wdt:P31/wdt:P279* wd:Q3914.
  ?sister wdt:P131* ?county.
  ?county wdt:P31/wdt:P279* wd:Q13410490.
  ?county wdt:P131 wd:Q1384.

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?country ?countryLabel WHERE {
  VALUES ?name { "Honoured Society"@en "The Honoured Society"@en }
  ?item rdfs:label ?name.
  ?item wdt:P31/wdt:P279* wd:Q3915489.
  ?item wdt:P17 ?country.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?state ?stateLabel WHERE {
  ?base rdfs:label "McClellan Air Force Base"@en.
  ?base wdt:P131+ ?state.
  ?state wdt:P31 wd:Q35657.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
LIMIT 1

SELECT DISTINCT ?city ?cityLabel WHERE {
  ?engine rdfs:label "Pirna 014"@en.
  VALUES ?rel { wdt:P287 wdt:P176 wdt:P61 }
  ?engine ?rel ?org.
  ?org wdt:P31/wdt:P279* wd:Q4830453;
       wdt:P17 wd:Q183;
       wdt:P159 ?city.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?faith ?faithLabel WHERE {
  ?univ rdfs:label "University of Providence"@en;
        wdt:P31/wdt:P279* wd:Q3918;
        wdt:P140 ?faith.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?album ?albumLabel WHERE {
  VALUES ?song { wd:QXXXX } 
  { ?song wdt:P361 ?album. }
  UNION
  { ?album wdt:P658 ?song. }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?album ?albumLabel WHERE {
  ?album wdt:P31 wd:Q482994;
         wdt:P175 ?artist;
         (wdt:P276|wdt:P1071|wdt:P483) ?place.
  ?artist rdfs:label "Guitars for Wounded Warriors"@en.

  ?place wdt:P131* ?area.
  ?area rdfs:label ?areaLabel.
  FILTER(LANG(?areaLabel) = "en" && CONTAINS(LCASE(STR(?areaLabel)), "village")).

  ?area wdt:P131* ?county.
  ?county rdfs:label "New York County"@en.

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?item ?itemLabel WHERE {
  ?item wdt:P31 wd:Q5;
        wdt:P27 wd:Q30;
        wdt:P569 ?dob.
  FILTER(YEAR(?dob)=1942 && MONTH(?dob)=5)

  ?item p:P26 ?spouseStmt.
  ?spouseStmt ps:P26 ?ex.
  ?spouseStmt pq:P582 ?end.
  ?ex wdt:P21 wd:Q6581097.

  ?battleSong wdt:P175 ?ex;
              wdt:P577 ?battleDate;
              wdt:P31/wdt:P279* wd:Q7366;
              rdfs:label "The Battle"@en.

  ?duetSong wdt:P175 ?item, ?ex;
            wdt:P577 ?duetDate;
            wdt:P31/wdt:P279* wd:Q7366.

  FILTER(YEAR(?duetDate) = YEAR(?battleDate))

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?person ?personLabel ?dob WHERE {
  {
    ?person wdt:P31 wd:Q5;
            rdfs:label "Francis Nethersole"@en;
            wdt:P569 ?dob.
  }
  UNION
  {
    ?person wdt:P31 wd:Q5;
            wdt:P26 ?spouse;
            wdt:P569 ?dob.
    ?spouse rdfs:label ?spLabel.
    FILTER(LANG(?spLabel)="en").
    FILTER(REGEX(?spLabel, "^Frederick V(,| of)"))
    ?person rdfs:label ?elLabel.
    FILTER(LANG(?elLabel)="en").
    FILTER(STRSTARTS(?elLabel, "Elizabeth Stuart"))
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?dob
LIMIT 1

SELECT DISTINCT ?what ?whatLabel WHERE {
  VALUES ?label { "Hacker-Pschorr Brewery"@en "Hacker-Pschorr"@en }
  ?brewery rdfs:label ?label.

  ?compliesProp a wikibase:Property; rdfs:label "complies with"@en; wikibase:directClaim ?compliesClaim.
  ?brewery ?compliesClaim ?reg.

  OPTIONAL { ?reg wdt:P17 ?country. }
  OPTIONAL { ?reg wdt:P1001 ?jurisdiction. }
  FILTER(?country = wd:Q183 || ?jurisdiction = wd:Q183)

  ?prop2 a wikibase:Property; wikibase:directClaim ?dc2; rdfs:label ?prop2Label.
  FILTER(LANG(?prop2Label)="en" && (CONTAINS(LCASE(?prop2Label), "limit") || CONTAINS(LCASE(?prop2Label), "restriction") || CONTAINS(LCASE(?prop2Label), "prohibit") || CONTAINS(LCASE(?prop2Label), "allowed")))
  ?reg ?dc2 ?what.

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?person ?personLabel WHERE {
  ?psi rdfs:label ?psiLabel.
  FILTER(LANG(?psiLabel)="en" && CONTAINS(LCASE(?psiLabel), "psychedelic shamanistic institute")).
  ?psi wdt:P112 ?founder.
  ?founder rdfs:label ?founderLabel.
  FILTER(LANG(?founderLabel)="en" && LCASE(?founderLabel) = "don barry mason").
  ?person wdt:P31 wd:Q5;
          wdt:P463 ?psi;
          wdt:P570 ?dod.
  FILTER(?person != ?founder).
  FILTER (YEAR(?dod) = 2016 && MONTH(?dod) = 4 && DAY(?dod) = 10).
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

