PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wikibase: <http://wikiba.se/ontology#>
PREFIX bd: <http://www.bigdata.com/rdf#>

SELECT DISTINCT ?mentor ?mentorLabel ?age WHERE {
  ?show rdfs:label "Splash!"@en;
        wdt:P31/wdt:P279* wd:Q5398426;
        wdt:P495 wd:Q145;
        wdt:P161 ?mentor.
  ?mentor wdt:P569 ?dob.

  ?event wdt:P1346 ?mentor;
         rdfs:label ?eventLabel;
         wdt:P361*/rdfs:label ?seriesLabel.
  FILTER(LANG(?eventLabel)="en").
  FILTER(LANG(?seriesLabel)="en").
  FILTER(CONTAINS(LCASE(?eventLabel), "platform")).
  FILTER(!CONTAINS(LCASE(?eventLabel), "synch")).
  FILTER(
    CONTAINS(LCASE(?seriesLabel), "2009 world aquatics championships") ||
    CONTAINS(LCASE(?seriesLabel), "2009 fina world championships")
  ).

  OPTIONAL { ?event wdt:P585 ?date. }
  OPTIONAL { ?event wdt:P580 ?start. }
  BIND(COALESCE(?date, ?start) AS ?winDate)
  FILTER(BOUND(?winDate))

  BIND(
    YEAR(?winDate) - YEAR(?dob) -
    IF(MONTH(?winDate) < MONTH(?dob) || (MONTH(?winDate) = MONTH(?dob) && DAY(?winDate) < DAY(?dob)), 1, 0)
    AS ?age
  )

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?occupation ?occupationLabel WHERE {
  {
    SELECT DISTINCT ?occupation WHERE {
      ?p1 rdfs:label "Am Rong"@en;
          wdt:P31 wd:Q5;
          wdt:P106 ?occupation.
    }
  }
  {
    SELECT DISTINCT ?occupation WHERE {
      ?p2 rdfs:label "Alexandre Rockwell"@en;
          wdt:P31 wd:Q5;
          wdt:P106 ?occupation.
    }
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?item ?itemLabel ?isSpecialInterest ?ownedByTimeInc WHERE {
  VALUES ?title { "El Nuevo Cojo"@en "Golf Magazine"@en }
  ?item rdfs:label ?title.

  ?timeInc rdfs:label "Time Inc."@en.

  BIND(
    (EXISTS {
      ?item wdt:P31 ?class.
      ?class rdfs:label ?classLabel.
      FILTER(LANG(?classLabel)="en" && CONTAINS(LCASE(?classLabel), "special") && CONTAINS(LCASE(?classLabel), "interest"))
    } || EXISTS {
      ?item wdt:P136 ?genre.
      ?genre rdfs:label ?genreLabel.
      FILTER(LANG(?genreLabel)="en" && CONTAINS(LCASE(?genreLabel), "special") && CONTAINS(LCASE(?genreLabel), "interest"))
    }) AS ?isSpecialInterest
  )

  BIND(EXISTS { ?item wdt:P127 ?timeInc } AS ?ownedByTimeInc)

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?funder ?funderLabel WHERE {
