  ?occ rdfs:label "bus driver"@en.
  { ?driver wdt:P463 ?team. } UNION { ?driver wdt:P54 ?team. }
  ?team wdt:P641 ?sport.
  ?sport rdfs:label "bowling"@en.
  { ?team wdt:P859 ?funder. } UNION { ?team wdt:P8324 ?funder. }
