SELECT ?author ?authorLabel WHERE {
  VALUES ?magName { "New Statesman"@en "The Nation"@en "The Atlantic"@en }
  ?mag rdfs:label ?magName.
  ?author wdt:P31 wd:Q5;
          wdt:P106/wdt:P279* wd:Q36180.
  { ?author wdt:P767 ?mag. } UNION { ?author wdt:P108 ?mag. }
  ?dyst rdfs:label "Dysteleology"@en.
  FILTER(EXISTS { ?author ?p ?dyst. })
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
