SELECT ?maker ?makerLabel WHERE {
  ?pres p:P39 ?posStmt.
  ?posStmt ps:P39 wd:Q11696; pq:P1545 "34".
  ?item wdt:P1535 ?pres; rdfs:label ?label.
  FILTER(LANG(?label) = "en").
  FILTER(CONTAINS(LCASE(?label), "pacemaker") && CONTAINS(LCASE(?label), "prototype")).
  OPTIONAL { ?item wdt:P176 ?manufacturer. }
  OPTIONAL { ?item wdt:P170 ?creator. }
  BIND(COALESCE(?manufacturer, ?creator) AS ?maker)
  FILTER(BOUND(?maker))
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

