  ?episode p:P4908 ?seasonStmt.
  ?seasonStmt ps:P4908 ?season;
              pq:P1545 "15".
  ?episode wdt:P161 ?person.

  FILTER EXISTS {
    ?person p:P166 ?emmyStmt.
    ?emmyStmt ps:P166 ?emmyAward.
    ?emmyAward wdt:P31/wdt:P279* wd:Q19020.
  }

  {
    SELECT ?person (COUNT(?tonyStmt) AS ?tonyWins) WHERE {
      ?person p:P166 ?tonyStmt.
      ?tonyStmt ps:P166 ?tonyAward.
      ?tonyAward wdt:P31/wdt:P279* wd:Q486748.
    } GROUP BY ?person
    HAVING (?tonyWins >= 2)
  }

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?mansion ?mansionLabel WHERE {
  {
    ?mayor p:P39 ?posStmt.
    ?posStmt ps:P39 ?office.
    ?office wdt:P279* wd:Q30185.
    ?posStmt pq:P1001 wd:Q23556; pq:P1545 "41".
  }
  UNION
  {
    ?office wdt:P1001 wd:Q23556; rdfs:label "Mayor of Atlanta"@en.
    {
      ?office p:P1308 ?holderStmt.
      ?holderStmt ps:P1308 ?mayor; pq:P1545 "41".
    }
    UNION
    {
      ?mayor p:P39 ?posStmt2.
      ?posStmt2 ps:P39 ?office; pq:P1545 "41".
    }
  }
  ?daughter wdt:P22 ?mayor; wdt:P21 wd:Q6581072.
  ?mansion wdt:P31/wdt:P279* wd:Q123705;
           wdt:P131 wd:Q23556.
  { ?mansion wdt:P88 ?daughter. } UNION { ?mansion wdt:P127 ?daughter. }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?inventor ?inventorLabel WHERE {
  VALUES ?label { "autograph"@en "signature"@en }
  ?item rdfs:label ?label.
  ?item wdt:P282 ?script.
  { ?script wdt:P61 ?inventor. }
  UNION
  { ?script wdt:P170 ?inventor. }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?ethnic ?ethnicLabel ?percentage WHERE {
  # Find the property "made to improve relations with" and its direct claim IRI
  ?propEntity a wikibase:Property;
              rdfs:label "made to improve relations with"@en;
              wikibase:directClaim ?improveRelProp.

  # Find the item "Princess Fragrant" (label or alias)
  ?work (rdfs:label|skos:altLabel) "Princess Fragrant"@en;
        ?improveRelProp ?ethnic.

  # Ensure it's an ethnic group and get its population
  ?ethnic wdt:P31 wd:Q41710;
          wdt:P1082 ?ethPop.

  # Get world (Earth) population
  wd:Q2 wdt:P1082 ?worldPop.

  BIND((xsd:decimal(?ethPop) / xsd:decimal(?worldPop) * 100) AS ?percentage)

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?person ?personLabel WHERE {
  ?proposal rdfs:label ?label.
  FILTER(LANG(?label) = "en").
  FILTER(CONTAINS(LCASE(?label), "boren") && CONTAINS(LCASE(?label), "mccurdy")).

  { ?proposal wdt:P138 ?person. }
  UNION
  { ?proposal wdt:P710 ?person. }

  ?person wdt:P106 wd:Q82955.

  FILTER (
    EXISTS {
      ?person p:P39 ?posStmt.
      ?posStmt pq:P768 ?district.
      ?district wdt:P131* wd:Q1649.
    } ||
    EXISTS { ?person wdt:P19/wdt:P131* wd:Q1649 } ||
    EXISTS { ?person wdt:P551/wdt:P131* wd:Q1649 }
  )

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
LIMIT 10

SELECT DISTINCT ?county ?countyLabel WHERE {
  ?stone rdfs:label "Thoen Stone"@en.
  {
    ?stone wdt:P276 ?museum.
  }
  UNION
  {
    ?stone wdt:P195 ?museum.
  }
  ?museum wdt:P31/wdt:P279* wd:Q33506.
  ?museum wdt:P131* ?county.
  ?county wdt:P31/wdt:P279* wd:Q13410422.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?hospital ?hospitalLabel ?beds WHERE {
  VALUES ?searchName { "MedStar Washington Hospital Center"@en "Children's National Medical Center"@en "Children's National Hospital"@en }
  ?hospital (rdfs:label|skos:altLabel) ?searchName.
  ?hospital wdt:P31/wdt:P279* wd:Q16917;
           wdt:P131* wd:Q61;
           wdt:P1083 ?beds.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?beds)
LIMIT 1
